    constructor(C _c) { c = _c; }

    // We take the wager amount and the whale address and wagerLimit only via the public surface of c.
    // run will: open the contract to public, set bet limit to a value, send exactly that amount in wager(),
    // then call play() immediately and check that play reverted.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Ensure contract is open to public so wager/play/donate paths are allowed.
        // Only the owner can call OpenToThePublic() on c; InvMutTest deployed c so it is owner.
        c.OpenToThePublic();

        // Adjust the bet limit to the provided amount so wager() will accept it.
        c.AdjustBetAmounts(amount);

        // Send the exact betLimit to c via wager(). Must be a top-level state-changing call.
        c.wager{value: amount}();

        // Now attempt to call play() immediately (same transaction, thus same block) and capture whether it reverts.
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Assert the general rule: when play is invoked in the same block as the recorded wager, it must revert.
        // We express this by requiring that reverted is true.
        assert(reverted == true);
    }

    // Allow contract to receive ETH so address(this).balance can be funded externally by the checker.
