contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two parameters: amount to use as wager (must equal current betLimit) and a dummy param
    // The test will: open to public, adjust bet limit to `amount` (owner-only), then have this contract
    // call wager() with value amount, simulate advancing block by requiring that play is called in a later block
    // (we cannot advance blocks here, but we will only call play if block.number > timestamps via trying and catching revert).
    // The assertion: after a successful play call (or after it reverts because called in same block), if play executed and returned
    // without reverting then hasPlayerWagered(this) must be false and balance of c decreased by at most amount.

    // Note: as InvMutTest is the owner (c was deployed by the checker with this contract as msg.sender), we can call owner-only functions.

    function run(uint256 betAmount, uint256 dummy) public payable {
        require(address(this).balance >= betAmount);

        // Set bet limit to desired wager amount
        c.AdjustBetAmounts(betAmount);
        // Open the contract to public so wager/play/donate are allowed
        c.OpenToThePublic();

        uint256 beforeBalance = address(c).balance;

        // Place the wager by sending exactly betAmount
        c.wager{value: betAmount}();

        // After wagering, contract should report that this address has a wager
        bool afterWagerHas = c.hasPlayerWagered(address(this));

        // Try to call play; it may revert if called in same block or if other require fails.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        uint256 afterBalance = address(c).balance;
        bool afterPlayHas = c.hasPlayerWagered(address(this));

        // General rule asserted:
        // If play did NOT revert (i.e., it executed), then the player's wager must have been cleared (hasPlayerWagered == false)
        // and the contract's balance cannot have decreased by more than the original wager (no more than betAmount was taken).
        // If play reverted, we don't require clearing. Also ensure we actually reached this assert in at least some execution.
        assert( playReverted || (afterPlayHas == false && beforeBalance >= afterBalance && (beforeBalance - afterBalance) <= betAmount) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require caller to supply exactly the bet amount and enough Ether to send.
    // The test: set bet limit to amount, open to public, place wager by sending amount, then call play()
    // and assert that if play did not revert then hasPlayerWagered(this) must be false.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount && amount > 0);

        // Make this contract the owner actions: adjust bet limit and open to public
        c.AdjustBetAmounts(amount);
        c.OpenToThePublic();

        // Place the wager by sending exactly amount
        c.wager{value: amount}();

        // Attempt to play; capture whether it reverted
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Assert the general invariant: if play executed then the player's recorded wager is cleared
        assert(playReverted || c.hasPlayerWagered(address(this)) == false);
    }

    receive() external payable {}
}

