contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to control owner actions and player actions.
    // ownerAddress is ignored by the test (owner is deployer of C), but we allow toggling openToPublic via calling OpenToThePublic()
    // amount is used to send Ether when calling wager/donate (must equal currentBetLimit for wager)
    function run(address whaleAddress, uint256 amount) public payable {
        require(true);
        // Make sure this contract has enough balance to forward Ether if needed
        // (The harness will fund this call if it wants to test payable behavior.)

        // 1) Ensure contract is open to public by calling OpenToThePublic from owner (this test contract is the deployer of C per harness)
        // This call must be top-level and will revert if caller is not owner; harness deploys C with this contract as owner.
        c.OpenToThePublic();

        // 2) Read current bet limit to drive correct wager amount
        uint256 currentLimit = c.currentBetLimit();

        // 3) Pre-condition: only attempt to wager using the current bet limit; if amount differs, we'll instead call donate
        bool wagered = false;
        bool playReverted = false;

        if (amount == currentLimit) {
            // ensure this contract has enough balance to send
            require(address(this).balance >= amount);
            // attempt to wager; this sets hasPlayerWagered to true for msg.sender inside C
            c.wager{value: amount}();
            wagered = c.hasPlayerWagered(address(this));
        } else {
            // send a donation if not matching bet limit (won't affect wagers mapping for this address)
            if (address(this).balance >= amount) {
                c.donate{value: amount}();
            }
            wagered = c.hasPlayerWagered(address(this));
        }

        // 4) Attempt to play. play() requires that timestamps[msg.sender] < block.number; to avoid revert due to equal block number
        // we just attempt play and catch whether it reverts. The rule will account for the revert flag.
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // 5) After the above sequence, assert the invariant:
        // If we successfully called wager with the exact bet limit (wagered == true) then hasPlayerWagered must be true
        // unless play succeeded and cleared the wager; therefore: hasPlayerWagered == (wagered && playReverted)
        // This expresses that a successful play (non-reverting) should clear the player's wager, while reverts leave it set.
        bool hasWagerNow = c.hasPlayerWagered(address(this));
        assert(hasWagerNow == (wagered && playReverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run drives: open the game, optionally wager by sending exact betLimit, then call play() and check relationship
    // params: amount - Ether to send when attempting wager (must equal betLimit to actually wager)
    function run(uint256 amount) public payable {
        require(true);
        // Ensure this contract has enough balance to forward Ether if needed
        // (the harness may fund this call)
        // 1) Open the contract to the public (this contract is the deployer/owner of C per harness)
        c.OpenToThePublic();

        // 2) Read current bet limit
        uint256 currentLimit = c.currentBetLimit();

        // 3) If amount == currentLimit and we have funds, perform wager; otherwise do nothing state-changing here
        bool didWagerCall = false;
        if (amount == currentLimit) {
            require(address(this).balance >= amount);
            c.wager{value: amount}();
            didWagerCall = true;
        }

        // 4) Record whether hasPlayerWagered after possible wager
        bool afterWager = c.hasPlayerWagered(address(this));

        // 5) Attempt to call play() and capture whether it reverted
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // 6) Record whether hasPlayerWagered after play
        bool afterPlay = c.hasPlayerWagered(address(this));

        // Assert the general rule:
        // - If we did not perform a matching wager call, hasPlayerWagered must not become true because of our actions here.
        // - If we did wager (sent exactly betLimit), then afterWager must be true.
        // - If we did wager and play did NOT revert, then the wager must be cleared (afterPlay == false).
        // - If we did wager and play reverted, the wager must remain (afterPlay == true).
        assert(
            // if we didn't call wager with exact amount, nothing we did should have made hasPlayerWagered true
            ((didWagerCall == false) ? (afterWager == false && afterPlay == false) : true)
            &&
            // if we did call wager, it must have set hasPlayerWagered immediately after
            ((didWagerCall == true) ? afterWager == true : true)
            &&
            // if wagered and play succeeded (didWagerCall && !playReverted) then afterPlay must be false
            ((didWagerCall == true && playReverted == false) ? afterPlay == false : true)
            &&
            // if wagered and play reverted then afterPlay must remain true
            ((didWagerCall == true && playReverted == true) ? afterPlay == true : true)
        );
    }

    // accept Ether so this contract can forward funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send amount equal to betLimit to wager if desired; msg.sender here is the test contract
    function run(uint256 amount) public payable {
        require(true);
        // open the game (owner = this contract as deployer in harness)
        c.OpenToThePublic();

        // read current bet limit
        uint256 currentLimit = c.currentBetLimit();

        // If caller chose to wager by supplying exactly the bet limit, forward Ether
        bool didWagerCall = false;
        if (amount == currentLimit) {
            require(address(this).balance >= amount);
            c.wager{value: amount}();
            didWagerCall = true;
        }

        // observe state after potential wager
        bool afterWager = c.hasPlayerWagered(address(this));

        // attempt to play and capture whether it reverted
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // observe state after play attempt
        bool afterPlay = c.hasPlayerWagered(address(this));

        // Single general assertion expressing the intended invariants
        assert(
            // If we called wager with exact betLimit, it must set hasPlayerWagered to true immediately
            ((didWagerCall) ? (afterWager == true) : (afterWager == false))
            &&
            // If we had wagered and play succeeded (didn't revert), the wager must be cleared
            ((didWagerCall && !playReverted) ? (afterPlay == false) : true)
